mkdir -p /tmp/mg && cat > /tmp/mg/grabc.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(){
    const char*out=getenv("GRABOUT"); if(!out) out="/tmp/mg/grab.txt";
    FILE*f=fopen(out,"w");
    char *line=NULL; size_t cap=0; ssize_t n;
    // 3 init lines
    for(int i=0;i<3;i++){ n=getline(&line,&cap,stdin); if(n<0) return 1; fwrite(line,1,n,f); }
    printf("G\n"); fflush(stdout);
    n=getline(&line,&cap,stdin); if(n>0) fwrite(line,1,n,f);
    fclose(f);
    return 0;
}
EOF
gcc -O2 -o /tmp/mg/grabc /tmp/mg/grabc.c && echo built
